/**
 * Уникальный текст для страницы города.
 *
 * Зачем это существует. Замерено на живом сайте до расширения: страница
 * города без поваров отдавала 270 видимых слов, а minsk.html и gomel.html
 * различались на два байта из двадцати двух тысяч. Это один шаблон с
 * подставленным названием — то есть дорвейная сеть, за которую понижают
 * домен целиком, включая работающие коммерческие лендинги /dostavka,
 * /obedy и /vypechka. Семнадцать зарубежных городов в такой форме сделали
 * бы сеть только убедительнее.
 *
 * Поэтому правило: НЕТ ЗАПИСИ — НЕТ СТРАНИЦЫ. Город без своего текста не
 * попадает ни в маршруты, ни в sitemap (см. publicRoutes в vite.config.ts).
 * Проверка для каждого абзаца простая: если его можно перенести на соседний
 * город, поменяв одно слово, — он не годится.
 *
 * И ограничение правдивости. Эти страницы описывают города, где Селина НЕ
 * работает. Ни один текст здесь не вправе обещать заказ, корзину, оплату,
 * доставку, «проверенных поваров» или называть число поваров: поваров нет
 * нигде, включая Россию. Разрешено ровно одно упоминание денег — рыночный
 * ориентир ЧУЖОГО сервиса, с его названием и в местной валюте.
 */
export interface CityFaq { q: string; a: string }

export interface CityContent {
  /** 2–3 предложения: что такое Селина и что здесь она пока не работает. */
  lead: string;
  /** Главный абзац: районы, рынки, чем город кормится. 150–220 слов. */
  local: string;
  /** Кто уже возит еду в этом городе и чего именно нет. */
  market: string;
  /** Обращение к повару: отметиться в списке, регистрация закрыта. */
  cook: string;
  /** Три вопроса, специфичных для города. Уходят в FAQPage-разметку. */
  faq: CityFaq[];
}

